package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "Ewe Mwenyezi Mungu, kwa Wewe tunaingia asubuhi na kwa ajili Yako tunaingia jioni; kwa Wewe tunaishi, na kwa Wewe tunakufa, na Kwako ni ufufuo.", "Asubuhi.", "Mtume ﷺ aliwafundisha Maswahaba kusema asubuhi na jioni hii."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "Ewe Mwenyezi Mungu, kwa Wewe tunaingia jioni na kwa ajili Yako tunaingia asubuhi; kwa Wewe tunaishi na kwa Wewe tunakufa, na Kwako ndio marejeo.", "Wakati wa jioni.", "Mtume ﷺ aliwafundisha Maswahaba kusema asubuhi na jioni hii."),
        "dua_afiyah_morning" to DuaText("Kuuliza kwa Afiyah", "Ewe Mwenyezi Mungu, nakuomba msamaha na kheri katika dunia na Akhera.", "Mtume ﷺ hakuwahi kuondoka katika dua hii, asubuhi au jioni.", "Hakuna mtu aliyepewa kitu bora zaidi kuliko ustawi."),
        "dua_afini_fi_badani" to DuaText("Afya ya Mwili, Kusikia na Kuona", "Ewe Mwenyezi Mungu, Ujaalie afya ya mwili wangu. Ewe Mwenyezi Mungu, nipe kheri masikioni mwangu. Ewe Mwenyezi Mungu nipe kheri machoni pangu. Hapana mungu ila Wewe.", "Mara tatu kila asubuhi na jioni.", "Dua ya afya na ulinzi wa hisi."),
        "dua_ya_hayyu_aslih" to DuaText("Rekebisha Mambo Yangu Yote", "Ewe Uliye hai, ewe Mlinzi, kwa rehema Zako naomba msaada: rekebisha mambo yangu yote na usiniache kwangu hata kwa kupepesa jicho.", "Mtume ﷺ alimshauri Fatimah (RA) aseme asubuhi na jioni.", "Kuomba msaada kwa Mwenyezi Mungu katika kila jambo."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbihi ya Juwayriyah (RA)", "Ametakasika Mwenyezi Mungu, na sifa njema zote ni Zake, kwa wingi wa viumbe vyake, kadiri anavyomridhisha, sawa na uzito wa Arshi yake na wino wa maneno yake.", "Mara tatu asubuhi - nzito kuliko masaa ya dhikr.", "Kusema maneno haya manne mara tatu kunazidi dhikr kuanzia alfajiri hadi katikati ya asubuhi."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "Ewe Mwenyezi Mungu mswalie Muhammad ﷺ na Aali Muhammad kama ulivyomsalia Ibrahim (AS) na ukoo wa Ibrahim. Wewe ni Mwenye kusifiwa, Mtukufu. Ewe Mwenyezi Mungu mbariki Muhammad ﷺ na Aali Muhammad kama ulivyombariki Ibrahim (AS) na ukoo wa Ibrahim; Wewe ni Mwenye kusifiwa, Mtukufu.", "Salawat juu ya Mtume ﷺ katika sala na wakati wote.", "Mwenye kuswali mara moja, Mwenyezi Mungu humteremshia rehema kumi (Muslim 408)."),
        "dua_wudu_after" to DuaText("Baada ya Wudhu", "Nashuhudia ya kwamba hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, Peke Yake, asiye na mshirika, na kwamba Muhammad ﷺ ni mja na Mtume Wake. Ewe Mwenyezi Mungu nijaalie niwe miongoni mwa wanaotubia na wanaojitakasa.", "Baada ya kumaliza wudhu.", "Milango minane ya Pepo inafunguliwa kwa ajili yake kuingia kwa apendavyo."),
        "dua_wudu_before" to DuaText("Kabla ya Wudhu", "Kwa jina la Mwenyezi Mungu.", "Wakati wa kuanza wudhu.", "Hakuna wudhu (kamili) kwa asiyetaja jina la Mwenyezi Mungu juu yake."),
        "dua_istiftah" to DuaText("Dua ya Ufunguzi (Sana)", "Umetakasika ewe Mwenyezi Mungu, na sifa njema ni Zako. Jina Lako limetukuka, utukufu wako umetukuka, na hakuna mungu ila Wewe.", "Mwanzoni mwa swala, mara tu baada ya takbira ya ufunguzi.", "Sunnah ya kufungua dua ya swala."),
        "dua_ruku" to DuaText("Katika Rukuu", "Utukufu ni wa Mola wangu Mlezi, Mtukufu.", "Angalau mara tatu katika rukuu.", "Tasbihi ya Sunnah ya rukuu."),
        "dua_sujood" to DuaText("Katika Sujuud", "Ametakasika Mola wangu Mlezi aliye juu.", "Angalau mara tatu katika sujood.", "Mja yu karibu zaidi na Mola wake akiwa katika sijda (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Kupanda kutoka Rukuu", "Mwenyezi Mungu humsikia anayemhimidi. Mola wetu Mlezi, sifa njema zote ni Zako.", "Huku akiinuka kutoka kwenye rukuu na kusimama wima.", "Yeyote ambaye 'Rabbana wa lakal-hamd' anasadifiana na Malaika, husamehewa madhambi yake yaliyopita."),
        "dua_between_sajdas" to DuaText("Baina ya Sajda Mbili", "Mola wangu Mlezi, nisamehe. Mola wangu Mlezi, nisamehe.", "Akiwa ameketi baina ya sijda mbili.", "Dua ya Sunnah ya kukaa baina ya sijda."),
        "dua_before_salam_four" to DuaText("Kimbilio kutokana na Mambo Manne (Kabla ya Salam)", "Ewe Mwenyezi Mungu, najikinga Kwako na adhabu ya Jahannam, na adhabu ya kaburi, na mitihani ya maisha na mauti, na shari ya mtihani wa Masihi wa Uongo (Dajjal).", "Baada ya tashahhud ya mwisho na salawat, kabla ya salamu.", "Mtume ﷺ aliamuru kutafuta hifadhi kutokana na mambo haya manne."),
        "dua_qunoot_witr" to DuaText("Qunoot katika Witr", "Ewe Mwenyezi Mungu, niongoze miongoni mwa wale uliowaongoza, nipe kheri miongoni mwa wale uliowaneemesha, niweke katika uangalizi Wako miongoni mwa wale uliowaweka chini ya uangalizi wako, nibariki katika ulichonipa, na unilinde kutokana na shari ya uliyoyahukumu. Unahukumu na hakuna anayekadiria juu Yako, na yule unayemfanyia urafiki haaibiki. Umebarikiwa na Umetukuka Wewe, Mola wetu.", "Katika swala ya witri - Mtume ﷺ alimfundisha Hasan ibn Ali (RA).", "Sunnah ya witr. (Miongoni mwa Hanafi, 'Allahumma inna nasta'inuka' pia inajulikana sana.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "Ewe Mwenyezi Mungu, tunakuomba msaada wako na msamaha wako, tunakuamini na kukutegemea Wewe, tunakusifu Wewe kwa njia bora, tunakushukuru na hatukufuru, na tunamuacha anayekuasi. Ewe Mwenyezi Mungu, Wewe tu tunakuabudu, Kwako tunakuomba na tunasujudu, Kwako tunafanya hima na tunapigania, tunataraji rehema Zako na tunaiogopa adhabu Yako; Hakika adhabu yako itawafikia makafiri.", "In witr - mazoezi ya Hanafi.", "Imeripotiwa kutoka kwa Umar (RA) kwenye qunoot."),
        "dua_sleep_aslamtu" to DuaText("Maneno ya Mwisho Kabla ya Kulala", "Ewe Mwenyezi Mungu, nimejisalimisha Kwako, nakabidhi jambo langu Kwako na niweke mgongo wangu kwenye ulinzi Wako, kwa kukutumaini Wewe na kukucha Wewe. Hapana pa kukimbilia na hapana pa kukimbilia Kwako isipokuwa Kwako. Ninakiamini Kitabu Chako Ulichoteremsha na Nabii Wako uliyemtuma.", "Baada ya udhu, kulala upande wa kulia - maneno ya mwisho kabla ya kulala.", "Akifa usiku huo, atakufa juu ya fitrah (Uislamu)."),
        "dua_waking_night" to DuaText("Kuamka Usiku", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake, na sifa njema ni zake, na Yeye ni Muweza wa kila kitu. Sifa njema zote ni za Mwenyezi Mungu, ametakasika, hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, Mwenyezi Mungu ndiye Mkubwa, na hakuna uwezo wala uwezo ila kwa Mwenyezi Mungu. Ewe Mwenyezi Mungu nisamehe.", "Wakati wa kuamka wakati wa usiku.", "Dua yake inajibiwa, na akiweka wudhu na akaswali, maombi yake yanakubaliwa."),
        "dua_hamm_ibn_masud" to DuaText("Dua ya huzuni (Ibn Mas'ud)", "Ewe Mwenyezi Mungu, mimi ni mja wako, mtoto wa mja wako, mtoto wa mjakazi wako. Paji langu liko mkononi mwako, amri yako juu yangu imetekelezwa, na amri yako juu yangu ni ya haki. Ninakuomba kwa kila jina lako ulilojitajia nalo, au uliloteremsha katika Kitabu Chako, au ulilomfundisha yeyote katika viumbe Wako, au ulilolihifadhi na nafsi Yako katika elimu ya ghaibu, kwamba Uifanye Qur'an kuwa chemchemi ya moyo wangu, nuru ya kifua changu, na kuniondolea huzuni yangu na kuondoka kwa wasiwasi wangu.", "Katika huzuni na dhiki - Mwenyezi Mungu hubadilisha huzuni na furaha.", "Mwenyezi Mungu humwondolea wasiwasi na huzuni na kumjaalia furaha badala yake."),
        "dua_difficulty_sahl" to DuaText("Wakati Kitu Ni Kigumu", "Ewe Mwenyezi Mungu, hakuna kilicho chepesi isipokuwa unachofanya kuwa rahisi, na wewe husahihisha yaliyo magumu ukitaka.", "Wakati kitu kinahisi kuwa kigumu.", "Urahisi katika mitihani na kazi ngumu."),
        "dua_musibah" to DuaText("Juu ya Msiba (Istirja)", "Sisi ni wa Mwenyezi Mungu na kwake tutarejea. Ewe Mwenyezi Mungu nipe malipo katika dhiki yangu na badala yake mimi nipe kilicho bora zaidi.", "Juu ya hasara au msiba wowote.", "Hakika Mwenyezi Mungu hutoa kilicho bora zaidi - Umm Salamah (RA) alipewa Mtume ﷺ."),
        "dua_debt" to DuaText("Kwa Unafuu wa Deni", "Ewe Mwenyezi Mungu, nitoshe kwa yale Uliyoyahalalisha Uliyoyaharamisha, na kwa fadhila Yako nijaalie niwe huru na wengine badala Yako.", "Kwa ajili ya kulipa deni - iliyofundishwa na Ali (RA).", "Hata kama deni ni kama mlima, Mwenyezi Mungu atalilipa."),
        "dua_anger" to DuaText("Wakati wa hasira", "Najikinga kwa Mwenyezi Mungu na Shet'ani aliyelaaniwa.", "Wakati hasira.", "Mtume ﷺ alisema: kama akisema hivi, hasira yake itaondoka."),
        "dua_waswasa" to DuaText("Dhidi ya Waswasa katika Imani", "Ninamuamini Mwenyezi Mungu na Mitume wake.", "Wakati minong'ono ya kishetani kuhusu imani njoo.", "Ikifika minong'ono, sema hivi na uishie hapo (na pia jikinge kwa Mwenyezi Mungu)."),
        "dua_travel_full" to DuaText("Dua Kamili ya Kusafiri", "Ewe Mwenyezi Mungu tunakuomba katika safari hii uadilifu na uchamungu, na matendo yanayokupendeza. Ewe Mwenyezi Mungu tufanyie wepesi safari hii na ufupishe umbali wake. Ewe Mwenyezi Mungu, Wewe ni Swahaba wa safari na Mlinzi wa familia.", "Wakati wa kuanza safari, baada ya 'Subhanalladhi sakhkhara'.", "Dua kamili ya safari ya Sunnah."),
        "dua_return_travel" to DuaText("Kurudi kutoka kwa Safari", "Tunarejea, tunatubu, tunamuabudu na kumsifu Mola wetu.", "Akirudi kutoka safarini.", "Mtume ﷺ alisema haya alipokuwa anarudi kutoka safarini."),
        "dua_farewell_traveller" to DuaText("Kuagana na Msafiri", "Nami nakabidhi kwa Mwenyezi Mungu Dini yenu, amana yenu na matokeo ya vitendo vyenu.", "Wakati wa kumuaga msafiri.", "Alichokabidhiwa Mwenyezi Mungu hakipotei kamwe."),
        "dua_entering_town" to DuaText("Kusimama Mahali", "Najikinga na maneno kamili ya Mwenyezi Mungu kutokana na shari ya kila alichoumba.", "Wakati wa kusimama mahali au kuwasili katika mji mpya.", "Hakuna kitakachomdhuru mpaka aondoke hapo."),
        "dua_boarding_ship" to DuaText("Kupanda Meli/Gari", "Kwa jina la Mwenyezi Mungu ni matanga yake na kutia nanga. Hakika Mola wangu Mlezi ni Msamehevu, Mwenye kurehemu.", "Wakati wa kupanda meli au gari - maneno ya Nabii Nuh (AS).", "Aya ya Kurani - dua ya safina ya Nuh (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar pamoja na Hayyul-Qayyum", "Naomba msamaha kwa Mwenyezi Mungu ambaye hapana mungu isipo kuwa Aliye hai, Mlinzi, na ninatubia kwake.", "Kwa ajili ya toba.", "Dhambi zake zimesamehewa hata kama alikuwa amekimbia kutoka kwenye uwanja wa vita."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Mola wangu Mlezi, samehe na urehemu, kwani Wewe ndiye mbora wa wanaorehemu.", "Dua ya Qur'an - ya msamaha na rehema.", "Aya ya mwisho ya Surah al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Umetakasika ewe Mwenyezi Mungu, na sifa njema ni Zako. Nashuhudia ya kwamba hapana mungu ila Wewe. Nakuomba msamaha na naelekea Kwako kwa toba.", "Wakati wa kuamka kutoka kwa mkusanyiko.", "Inakuwa ni kafara ya kosa lolote lililosemwa katika mkusanyiko."),
        "dua_jami_forgiveness" to DuaText("Msamaha wa Kina", "Ewe Mwenyezi Mungu, nisamehe makosa yangu, ujinga wangu, kupita kiasi kwangu katika mambo yangu, na yote unayoyajua zaidi kuliko mimi.", "Dua kamili ya Mtume ﷺ.", "Mtume ﷺ alikuwa akifanya dua hii."),
        "dua_parents_nuh" to DuaText("Dua ya Nuh (AS) kwa Wazazi", "Mola wangu Mlezi, nighufirie enyi wazazi wangu wawili, mwenye kuingia nyumbani kwangu akiwa ni Muumini, na Waumini wanaume na Waumini wanawake.", "Kwa wazazi wa mtu na Waumini.", "Dua ya Nabii Nuh (AS)."),
        "dua_shukr_parents" to DuaText("Shukrani kwa Wazazi na Wazao Waadilifu", "Mola wangu Mlezi, niwezeshe kushukuru neema Yako uliyonineemesha mimi na wazazi wangu wawili, na nifanye vitendo vyema unavyoridhia, na uwajaalie dhuriya wangu. Natubia Kwako na mimi ni miongoni mwa waliosilimu.", "Dua ya Quran ya kufikia umri wa miaka arobaini.", "Shukrani, matendo mema na uadilifu wa watoto wa mtu - yote katika dua moja."),
        "dua_intimacy" to DuaText("Kabla ya Mahusiano ya Ndoa", "Kwa jina la Mwenyezi Mungu. Ewe Mwenyezi Mungu, tuepushe na shetani na umuepushe na (watoto) unaoturuzuku.", "Kabla ya mahusiano ya ndoa.", "Mtoto akiandikiwa shaytwaan hatamdhuru."),
        "dua_ibrahim_children_protection" to DuaText("Ulinzi wa Nyumbani na Watoto", "Mola wangu Mlezi, ufanye mji huu kuwa salama na uniepushe mimi na watoto wangu na kuabudu masanamu.", "Dua ya Nabii Ibrahim (AS) - kwa usalama wa mji na watoto wake.", "Dua ya kubaki imara juu ya tawhid."),
        "dua_drinking_milk" to DuaText("Wakati wa Kunywa Maziwa", "Ewe Mwenyezi Mungu, tubariki na utupe zaidi katika hayo.", "Wakati wa kunywa maziwa.", "Maziwa yanatosha kama chakula na kinywaji."),
        "dua_iftar_host" to DuaText("Wakati wa Kufunga na Wengine", "Watu waliofunga na wafungue saumu pamoja nawe, wenye haki wakule chakula chako, na malaika wakuombee.", "Wakati wa kufungua mfungo nyumbani kwa mtu.", "Dua ya Mtume ﷺ kwa mwenyeji."),
    )
}
